import { RefObject, useLayoutEffect } from 'react';

import { useAnnotationsTooltipState } from './store/selectors.js';

/**
 * Attaches event listeners to the referenced component to enable calling
 * the HideTooltip method whenever a click event occurs outside of it or
 * the escape key is pressed.
 *
 * @param ref - Ref object of the component to attach the event listeners to.
 * @param hideTooltip - Function that hides the tooltip when triggered.
 */
export const useRegisterTooltipHandlerCallbacks = (
  ref: RefObject<HTMLElement>,
  hideTooltip: () => void,
) => {
  const { pinned } = useAnnotationsTooltipState();
  useLayoutEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (pinned && event.key === 'Escape') {
        hideTooltip();
      }
    };

    const handleOutsideClick = (event: MouseEvent) => {
      const currentTarget = event.target;
      const refCurrent = ref.current;

      if (pinned && refCurrent && !refCurrent.contains(currentTarget as Node)) {
        hideTooltip();
      }
    };

    if (pinned) {
      document.addEventListener('keydown', handleKeyDown);
      document.addEventListener('click', handleOutsideClick);
    }

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.removeEventListener('click', handleOutsideClick);
    };
  }, [pinned, ref]);
};
